import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Addizione fra numeri naturali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/ba/bad.md","filePath":"lezioni/b_aritmetica-e-numeri/ba/bad.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/ba/bad.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="addizione-fra-numeri-naturali" tabindex="-1">Addizione fra numeri naturali <a class="header-anchor" href="#addizione-fra-numeri-naturali" aria-label="Permalink to “Addizione fra numeri naturali”">​</a></h1><p>D&#39;ora in avanti useremo indifferentemente i termini somma e addizione anche se la somma indica il risultato mentre l&#39;addizione indica l&#39;operazione.</p><blockquote><p><strong>Nota:</strong> Per iniziare una piccola precisazione: quando in matematica dobbiamo trovare delle regole cerchiamo sempre di rifarci a qualcosa di precedente, se non è possibile riferirsi a qualcosa di preesistente si cerca di seguire la strada più semplice. In questo caso ci rifacciamo alla somma di segmenti perché più intuitiva.</p></blockquote><p>Disegno su una semiretta l&#39;insieme dei numeri naturali:</p><p>Se voglio fare <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="blue"><mn>3</mn></mstyle><mo>+</mo><mstyle mathcolor="green"><mn>2</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{3} + \\textcolor{green}{2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord" style="color:blue;">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:green;">2</span></span></span></span></p><p>disegno a partire da <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> un segmento lungo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> ed un segmento lungo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>.</p><p>Per sommare metto in fila i segmenti e vedo che ottengo un segmento che termina in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn></mrow><annotation encoding="application/x-tex">5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>.</p><p>quindi</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mn>3</mn></mstyle><mo>+</mo><mstyle mathcolor="green"><mn>2</mn></mstyle><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{3} + \\textcolor{green}{2} = 5 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord" style="color:blue;">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:green;">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span></span></p><p>C&#39;è subito da dire che facendo la somma fra numeri naturali mi muovo sempre verso destra e, a destra, i numeri sono infiniti; quindi potrò sempre fare l&#39;addizione cioè l&#39;addizione fra numeri naturali è un&#39;operazione interna e l&#39;insieme <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> è chiuso rispetto all&#39;addizione.</p><p>Fra tutti i numeri naturali ne esiste uno particolare: lo zero; lo zero ha la proprietà di non cambiare niente infatti preso un numero qualunque:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>0</mn><mo>+</mo><mtext>numero</mtext><mo>=</mo><mtext>numero</mtext><mo>+</mo><mn>0</mn><mo>=</mo><mtext>numero</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{0 + \\text{numero} = \\text{numero} + 0 = \\text{numero}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord" style="color:red;">0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span></span></span></span></span></p><p>Si esprime questo fatto dicendo che:</p><p><strong>[zero è l&#39;elemento neutro per l&#39;addizione]{.text-red-darken-1}</strong></p><p>questa proprietà sarà sempre valida per tutti i numeri: naturali, interi, razionali, reali, complessi.</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};